import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Score and pattern tracking
    my_score = 0
    opp_score = 0
    opp_def = 0
    opp_c = 0
    my_c = 0
    cc = cd = dc = dd = 0
    for me, op in history:
        if me == 'C' and op == 'C':
            my_score += 3
            opp_score += 3
            cc += 1
            opp_c += 1
            my_c += 1
        elif me == 'C' and op == 'D':
            opp_score += 5
            cd += 1
            opp_def += 1
            my_c += 1
        elif me == 'D' and op == 'C':
            my_score += 5
            dc += 1
            opp_c += 1
        else:
            my_score += 1
            opp_score += 1
            dd += 1
            opp_def += 1

    last_me, last_op = history[-1]

    # Always defect against an all-defector
    if opp_def == n:
        return 'D'

    # If opponent has never defected, cooperate but exploit late
    if opp_def == 0:
        remaining = 100 - n
        if remaining <= 1:
            return 'D'
        if remaining <= 5 and rng.random() < 0.4:
            return 'D'
        return 'C'

    # Detect recent defection streak for the opponent
    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak += 1
        else:
            break

    # Grim-ish: if opponent defected many times recently, punish harder
    recent = history[-10:]
    recent_opp_def = sum(1 for _, op in recent if op == 'D')
    recent_my_def = sum(1 for me, _ in recent if me == 'D')

    # Opponent just defected
    if last_op == 'D':
        if streak >= 3:
            # Punish, but occasionally try to reset
            if streak % 5 == 0:
                return 'C'
            return 'D'
        if streak == 2:
            return 'D'
        # Single recent defection: mostly retaliate but sometimes forgive
        if cd * 3 < cc and recent_opp_def <= 2 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    # If we've been exploited a lot (they defected while we cooperated), be wary
    if cd > cc and n >= 6:
        if rng.random() < 0.45:
            return 'D'

    # If opponent recently defected a lot, be cautious
    if recent_opp_def >= 4 and n >= 8:
        if rng.random() < 0.6:
            return 'D'

    # Behind in score: probe more
    if opp_score > my_score + 8 and n >= 5:
        if rng.random() < 0.25:
            return 'D'

    # If we've been defecting recently and opponent is still cooperating, return to C
    if last_me == 'D' and recent_my_def >= 2:
        return 'C'

    # Late game exploitation when opponent is very cooperative
    remaining = 100 - n
    if opp_c > 0 and opp_def * 4 < n:
        if remaining <= 3 and rng.random() < 0.6:
            return 'D'
        if remaining <= 8 and rng.random() < 0.15:
            return 'D'

    return 'C'
